  IF v_count=0 THEN
    INSERT INTO chapters (module_id,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_module,'Where Do You Live?','کجا زندگی می‌کنی؟','Arman learns to say where he lives and separates residence from origin.','آرمان یاد می‌گیرد محل زندگی‌اش را بگوید و آن را از مبدأ جدا کند.',4,1,1,3,'validated',JSON_OBJECT('series',3,'contractVersion','3.0.0','level','A1','generatedStatus','locally_validated')); SET v_chapter=LAST_INSERT_ID();
