      (v_course,'pronunciation','en:a1:pron:w-vs-v-intro','where — /w/ onset',NULL,'شروع تشخیص /w/ در where بدون تبدیل به /v/','A1',1,JSON_OBJECT('target','w_vs_v'),JSON_OBJECT('series',3));
