      (v_chapter,v_c_maya,v_c_arman,'Where Do You Live?','کجا زندگی می‌کنی؟','Maya asks about Arman''s home in London.','مایا درباره محل زندگی آرمان در لندن می‌پرسد.','story','london_new_start',9,1,420,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
