    UPDATE curriculum_outcomes SET evidence=JSON_ARRAY_APPEND(COALESCE(evidence,JSON_ARRAY()),'$','EN-CH-0003'),status='in_progress' WHERE course_id=v_course AND cefr_level='A1' AND outcome_key IN ('can_do:state_residence','grammar:present-simple-basic','lexical:home-routine-residence','pron:w-vs-v','reading:short_identity','listening:key-place-info');
  ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='chapter identity not unique'; END IF;
